Até agora o objeto respondia a perguntas sobre campos ESPECÍFICOS: `aluno.nome`, `aluno['idade']`. Mas e quando queremos saber TUDO que tem dentro — sem saber os nomes de antemão?

O JavaScript entrega três funções prontas, uma para cada "visão" do objeto:

- **Object.keys(objeto)** — a lista dos RÓTULOS (chaves);
- **Object.values(objeto)** — a lista dos VALORES;
- **Object.entries(objeto)** — a lista de PARES `[chave, valor]`.

```
const aluno = { nome: 'Ana', idade: 15, cidade: 'São Paulo' };

Object.keys(aluno);    // ['nome', 'idade', 'cidade']
Object.values(aluno);  // ['Ana', 15, 'São Paulo']
Object.entries(aluno); // [['nome', 'Ana'], ['idade', 15], ['cidade', 'São Paulo']]
```

**Analogia:** o objeto é um armário com gavetas etiquetadas. `keys` é a lista das etiquetas; `values` é o conteúdo de cada gaveta; `entries` é a lista de "etiqueta + conteúdo" juntos.

Com a lista de entries dá para percorrer TUDO do objeto num `for...of` — a cada volta, uma dupla `[chave, valor]`:

```
for (const [chave, valor] of Object.entries(aluno)) {
  console.log(chave, valor);
}
```

code.code:
const aluno = { nome: 'Ana', idade: 15, cidade: 'São Paulo' };

console.log(Object.keys(aluno));    // [ 'nome', 'idade', 'cidade' ]
console.log(Object.values(aluno));  // [ 'Ana', 15, 'São Paulo' ]
console.log(Object.entries(aluno)); // [ [ 'nome', 'Ana' ], [ 'idade', 15 ], [ 'cidade', 'São Paulo' ] ]

// Percorrer tudo com entries: cada volta entrega [chave, valor].
for (const [chave, valor] of Object.entries(aluno)) {
  console.log(`${chave} = ${valor}`);
}
// nome = Ana
// idade = 15
// cidade = São Paulo

const estoque = { caneta: 2, caderno: 5, borracha: 1 };

// hasOwnProperty: pergunta pelo rótulo.
console.log(estoque.hasOwnProperty('caneta')); // true
console.log(estoque.hasOwnProperty('lapis'));  // false

// Somar os valores — Object.values vira lista, for...of soma.
let total = 0;
for (const valor of Object.values(estoque)) {
  total = total + valor;
}
console.log(total); // 8

// Descobrir a chave do maior valor — entries + comparação.
let melhor = null;
for (const [chave, valor] of Object.entries(estoque)) {
  if (melhor === null || valor > melhor.valor) {
    melhor = { chave, valor };
  }
}
console.log(melhor); // { chave: 'caderno', valor: 5 }

// Passo 1: os nomes dos produtos = as chaves.
function nomesDosProdutos(estoque) {
  return Object.keys(estoque);
}

// Passo 2: o valor total = soma dos valores.
function valorTotal(estoque) {
  let total = 0;
  for (const valor of Object.values(estoque)) {
    total = total + valor;
  }
  return total;
}

// Passo 3: o mais caro = maior valor, devolvendo o NOME (a chave).
function produtoMaisCaro(estoque) {
  let melhor = null;
  for (const [chave, valor] of Object.entries(estoque)) {
    if (melhor === null || valor > melhor.valor) {
      melhor = { chave, valor };
    }
  }
  return melhor === null ? null : melhor.chave;
}

// Passo 4: os três com um estoque de verdade e com o vazio.
const estoque = { caneta: 2, caderno: 5, borracha: 1 };
console.log(nomesDosProdutos(estoque)); // [ 'caneta', 'caderno', 'borracha' ]
console.log(valorTotal(estoque));       // 8
console.log(produtoMaisCaro(estoque));  // caderno

const vazio = {};
console.log(valorTotal(vazio));         // 0
console.log(produtoMaisCaro(vazio));    // null
